    .tiny_npu_d_m_axi_arlen      ( tiny_npu_d_m_axi_arlen           ),
    .tiny_npu_d_m_axi_arsize     ( tiny_npu_d_m_axi_arsize          ),
    .tiny_npu_d_m_axi_arburst    ( tiny_npu_d_m_axi_arburst         ),
    .tiny_npu_d_m_axi_arlock     ( tiny_npu_d_m_axi_arlock          ),
    .tiny_npu_d_m_axi_arcache    ( tiny_npu_d_m_axi_arcache         ),
    .tiny_npu_d_m_axi_arprot     ( tiny_npu_d_m_axi_arprot          ),
    .tiny_npu_d_m_axi_arvalid    ( tiny_npu_d_m_axi_arvalid         ),
    .tiny_npu_d_m_axi_arready    ( tiny_npu_d_m_axi_arready         ),
    .tiny_npu_d_m_axi_rid        ( tiny_npu_d_m_axi_rid             ),
    .tiny_npu_d_m_axi_rdata      ( tiny_npu_d_m_axi_rdata           ),
    .tiny_npu_d_m_axi_rresp      ( tiny_npu_d_m_axi_rresp           ),
    .tiny_npu_d_m_axi_rlast      ( tiny_npu_d_m_axi_rlast           ),
    .tiny_npu_d_m_axi_rvalid     ( tiny_npu_d_m_axi_rvalid          ),
    .tiny_npu_d_m_axi_rready     ( tiny_npu_d_m_axi_rready          )
  );

  // 3. ITCM (CPU Internal RAM)
  // Full addresses must be checked before RAM address-port truncation.
  // Reject invalid/wrapping transfers by backpressure; reset is recovery.
  function automatic bram_span_ok;
    input [31:0] addr;
    input [7:0] len;
    input [2:0] size;
    input [1:0] burst;
    input [31:0] base;
    input [32:0] bytes_count;
    reg [32:0] first_byte, end_byte;
    begin
      first_byte={1'b0,addr};
      end_byte=first_byte+((33'd1+len)<<size);
      bram_span_ok=(burst==2'b01 || len==0) && first_byte>={1'b0,base} &&
                   end_byte<=({1'b0,base}+bytes_count);
    end
  endfunction
  wire io_ramAxi_aw_in_range=bram_span_ok(io_ramAxi_aw_payload_addr,io_ramAxi_aw_payload_len,io_ramAxi_aw_payload_size,io_ramAxi_aw_payload_burst,32'h80000000,ITCM_BYTES);
  wire io_ramAxi_aw_ram_ready;
  assign io_ramAxi_aw_ready=io_ramAxi_aw_ram_ready && io_ramAxi_aw_in_range;
  wire io_ramAxi_ar_in_range=bram_span_ok(io_ramAxi_ar_payload_addr,io_ramAxi_ar_payload_len,io_ramAxi_ar_payload_size,io_ramAxi_ar_payload_burst,32'h80000000,ITCM_BYTES);
  wire io_ramAxi_ar_ram_ready;
  assign io_ramAxi_ar_ready=io_ramAxi_ar_ram_ready && io_ramAxi_ar_in_range;
  wire io_externalAxi_aw_in_range=bram_span_ok(io_externalAxi_aw_payload_addr,io_externalAxi_aw_payload_len,io_externalAxi_aw_payload_size,io_externalAxi_aw_payload_burst,32'hA0000000,EXTERNAL_BYTES);
  wire io_externalAxi_aw_ram_ready;
  assign io_externalAxi_aw_ready=io_externalAxi_aw_ram_ready && io_externalAxi_aw_in_range;
  wire io_externalAxi_ar_in_range=bram_span_ok(io_externalAxi_ar_payload_addr,io_externalAxi_ar_payload_len,io_externalAxi_ar_payload_size,io_externalAxi_ar_payload_burst,32'hA0000000,EXTERNAL_BYTES);
  wire io_externalAxi_ar_ram_ready;
  assign io_externalAxi_ar_ready=io_externalAxi_ar_ram_ready && io_externalAxi_ar_in_range;
  wire tiny_npu_d_m_axi_aw_in_range=bram_span_ok(tiny_npu_d_m_axi_awaddr,tiny_npu_d_m_axi_awlen,tiny_npu_d_m_axi_awsize,tiny_npu_d_m_axi_awburst,32'h00000000,EXTERNAL_BYTES);
  wire tiny_npu_d_m_axi_aw_ram_ready;
  assign tiny_npu_d_m_axi_awready=tiny_npu_d_m_axi_aw_ram_ready && tiny_npu_d_m_axi_aw_in_range;
  wire tiny_npu_d_m_axi_ar_in_range=bram_span_ok(tiny_npu_d_m_axi_araddr,tiny_npu_d_m_axi_arlen,tiny_npu_d_m_axi_arsize,tiny_npu_d_m_axi_arburst,32'h00000000,EXTERNAL_BYTES);
  wire tiny_npu_d_m_axi_ar_ram_ready;
  assign tiny_npu_d_m_axi_arready=tiny_npu_d_m_axi_ar_ram_ready && tiny_npu_d_m_axi_ar_in_range;

  axi_ram # (
    .DATA_WIDTH ( 32        ),
    .ADDR_WIDTH ( ITCM_SIZE ),
    .ID_WIDTH   ( 4         ),
    .RAM_WORDS  ( ITCM_BYTES/4 ),
    .INIT_FILE  ( FIRMWARE_FILE )
  ) u_itcm (
    .clk           ( cpu_clk                    ),
    .rst           ( ~cpu_rst_n                 ), // Check active level!
    .s_axi_awid    ( io_ramAxi_aw_payload_id    ),
    .s_axi_awaddr  ( io_ramAxi_aw_payload_addr  ), 
    .s_axi_awlen   ( io_ramAxi_aw_payload_len   ),
    .s_axi_awsize  ( io_ramAxi_aw_payload_size  ),
    .s_axi_awburst ( io_ramAxi_aw_payload_burst ),
    .s_axi_awlock  ( io_ramAxi_aw_payload_lock  ),
    .s_axi_awcache ( io_ramAxi_aw_payload_cache ),
    .s_axi_awprot  ( io_ramAxi_aw_payload_prot  ),
    .s_axi_awvalid ( io_ramAxi_aw_valid && io_ramAxi_aw_in_range         ),
    .s_axi_awready ( io_ramAxi_aw_ram_ready         ),
    .s_axi_wdata   ( io_ramAxi_w_payload_data   ),
    .s_axi_wstrb   ( io_ramAxi_w_payload_strb   ),
    .s_axi_wlast   ( io_ramAxi_w_payload_last   ),
    .s_axi_wvalid  ( io_ramAxi_w_valid          ),
    .s_axi_wready  ( io_ramAxi_w_ready          ),
    .s_axi_bid     ( io_ramAxi_b_payload_id     ),
    .s_axi_bresp   ( io_ramAxi_b_payload_resp   ),
    .s_axi_bvalid  ( io_ramAxi_b_valid          ),
    .s_axi_bready  ( io_ramAxi_b_ready          ),
    .s_axi_arid    ( io_ramAxi_ar_payload_id    ),
    .s_axi_araddr  ( io_ramAxi_ar_payload_addr  ), 
    .s_axi_arlen   ( io_ramAxi_ar_payload_len   ),
    .s_axi_arsize  ( io_ramAxi_ar_payload_size  ),
    .s_axi_arburst ( io_ramAxi_ar_payload_burst ),
    .s_axi_arlock  ( io_ramAxi_ar_payload_lock  ),
    .s_axi_arcache ( io_ramAxi_ar_payload_cache ),
    .s_axi_arprot  ( io_ramAxi_ar_payload_prot  ),
    .s_axi_arvalid ( io_ramAxi_ar_valid && io_ramAxi_ar_in_range         ),
    .s_axi_arready ( io_ramAxi_ar_ram_ready         ),
    .s_axi_rid     ( io_ramAxi_r_payload_id     ),
    .s_axi_rdata   ( io_ramAxi_r_payload_data   ),
    .s_axi_rresp   ( io_ramAxi_r_payload_resp   ),
    .s_axi_rlast   ( io_ramAxi_r_payload_last   ),
    .s_axi_rvalid  ( io_ramAxi_r_valid          ),
    .s_axi_rready  ( io_ramAxi_r_ready          )
  );

  // 4. External Dual Port RAM (Port A: CPU, Port B: NPU)
  // The generated Vex external AXI data path is 32 bits while NPU DMA is
  // 64 bits. Keep the addressed 32-bit lane on each AXI beat.
  reg [31:0] cpu_ext_write_addr;
  reg [31:0] cpu_ext_read_addr;
  wire [63:0] cpu_ext_wdata64 = cpu_ext_write_addr[2] ?
      {io_externalAxi_w_payload_data, 32'b0} :
      {32'b0, io_externalAxi_w_payload_data};
  wire [7:0] cpu_ext_wstrb8 = cpu_ext_write_addr[2] ?
      {io_externalAxi_w_payload_strb, 4'b0} :
      {4'b0, io_externalAxi_w_payload_strb};
  wire [63:0] cpu_ext_rdata64;
  assign io_externalAxi_r_payload_data = cpu_ext_read_addr[2] ?
      cpu_ext_rdata64[63:32] : cpu_ext_rdata64[31:0];
  always @(posedge cpu_clk) begin
      if (!cpu_rst_n) begin
          cpu_ext_write_addr <= 0;
          cpu_ext_read_addr <= 0;
      end else begin
          if (io_externalAxi_aw_valid && io_externalAxi_aw_ready)
              cpu_ext_write_addr <= io_externalAxi_aw_payload_addr;
          else if (io_externalAxi_w_valid && io_externalAxi_w_ready)
              cpu_ext_write_addr <= cpu_ext_write_addr + 4;
          if (io_externalAxi_ar_valid && io_externalAxi_ar_ready)
              cpu_ext_read_addr <= io_externalAxi_ar_payload_addr;
          else if (io_externalAxi_r_valid && io_externalAxi_r_ready)
              cpu_ext_read_addr <= cpu_ext_read_addr + 4;
      end
  end
  axi_dp_ram # (
    .DATA_WIDTH ( `DATA_WIDTH       ),
    .ADDR_WIDTH ( EXTERNAL_ADDR_BITS ),
    .ID_WIDTH   ( 4                 ),
    .RAM_WORDS  ( EXTERNAL_BYTES/8 )
  ) u_external_ram (
    // Port A (CPU)
    .a_clk           ( cpu_clk                        ),
    .a_rst           ( ~cpu_rst_n                     ),
    .s_axi_a_awid    ( io_externalAxi_aw_payload_id   ),
    .s_axi_a_awaddr  ( io_externalAxi_aw_payload_addr ),
    .s_axi_a_awlen   ( io_externalAxi_aw_payload_len  ),
    .s_axi_a_awsize  ( io_externalAxi_aw_payload_size ),
    .s_axi_a_awburst ( io_externalAxi_aw_payload_burst),
    .s_axi_a_awlock  ( io_externalAxi_aw_payload_lock ),
    .s_axi_a_awcache ( io_externalAxi_aw_payload_cache),
    .s_axi_a_awprot  ( io_externalAxi_aw_payload_prot ),
    .s_axi_a_awvalid ( io_externalAxi_aw_valid && io_externalAxi_aw_in_range        ),
    .s_axi_a_awready ( io_externalAxi_aw_ram_ready        ),
    .s_axi_a_wdata   ( cpu_ext_wdata64                 ),
    .s_axi_a_wstrb   ( cpu_ext_wstrb8                  ),
    .s_axi_a_wlast   ( io_externalAxi_w_payload_last  ),
    .s_axi_a_wvalid  ( io_externalAxi_w_valid         ),
    .s_axi_a_wready  ( io_externalAxi_w_ready         ),
    .s_axi_a_bid     ( io_externalAxi_b_payload_id    ),
    .s_axi_a_bresp   ( io_externalAxi_b_payload_resp  ),
    .s_axi_a_bvalid  ( io_externalAxi_b_valid         ),
    .s_axi_a_bready  ( io_externalAxi_b_ready         ),
    .s_axi_a_arid    ( io_externalAxi_ar_payload_id   ),
    .s_axi_a_araddr  ( io_externalAxi_ar_payload_addr ),
    .s_axi_a_arlen   ( io_externalAxi_ar_payload_len  ),
    .s_axi_a_arsize  ( io_externalAxi_ar_payload_size ),
    .s_axi_a_arburst ( io_externalAxi_ar_payload_burst),
    .s_axi_a_arlock  ( io_externalAxi_ar_payload_lock ),
    .s_axi_a_arcache ( io_externalAxi_ar_payload_cache),
    .s_axi_a_arprot  ( io_externalAxi_ar_payload_prot ),
    .s_axi_a_arvalid ( io_externalAxi_ar_valid && io_externalAxi_ar_in_range        ),
    .s_axi_a_arready ( io_externalAxi_ar_ram_ready        ),
    .s_axi_a_rid     ( io_externalAxi_r_payload_id    ),
    .s_axi_a_rdata   ( cpu_ext_rdata64                 ),
    .s_axi_a_rresp   ( io_externalAxi_r_payload_resp  ),
    .s_axi_a_rlast   ( io_externalAxi_r_payload_last  ),
    .s_axi_a_rvalid  ( io_externalAxi_r_valid         ),
    .s_axi_a_rready  ( io_externalAxi_r_ready         ),

    // Port B (NPU)
    .b_clk           ( npu_clk                        ),
    .b_rst           ( ~npu_rst_n                     ),
    .s_axi_b_awid    ( tiny_npu_d_m_axi_awid          ),
    .s_axi_b_awaddr  ( tiny_npu_d_m_axi_awaddr        ),
    .s_axi_b_awlen   ( tiny_npu_d_m_axi_awlen         ),
    .s_axi_b_awsize  ( tiny_npu_d_m_axi_awsize        ),
    .s_axi_b_awburst ( tiny_npu_d_m_axi_awburst       ),
    .s_axi_b_awlock  ( tiny_npu_d_m_axi_awlock        ),
    .s_axi_b_awcache ( tiny_npu_d_m_axi_awcache       ),
    .s_axi_b_awprot  ( tiny_npu_d_m_axi_awprot        ),
    .s_axi_b_awvalid ( tiny_npu_d_m_axi_awvalid && tiny_npu_d_m_axi_aw_in_range       ),
    .s_axi_b_awready ( tiny_npu_d_m_axi_aw_ram_ready       ),
    .s_axi_b_wdata   ( tiny_npu_d_m_axi_wdata         ),
    .s_axi_b_wstrb   ( tiny_npu_d_m_axi_wstrb         ),
    .s_axi_b_wlast   ( tiny_npu_d_m_axi_wlast         ),
    .s_axi_b_wvalid  ( tiny_npu_d_m_axi_wvalid        ),
    .s_axi_b_wready  ( tiny_npu_d_m_axi_wready        ),
    .s_axi_b_bid     ( tiny_npu_d_m_axi_bid           ),
    .s_axi_b_bresp   ( tiny_npu_d_m_axi_bresp         ),
    .s_axi_b_bvalid  ( tiny_npu_d_m_axi_bvalid        ),
    .s_axi_b_bready  ( tiny_npu_d_m_axi_bready        ),
    .s_axi_b_arid    ( tiny_npu_d_m_axi_arid          ),
    .s_axi_b_araddr  ( tiny_npu_d_m_axi_araddr        ),
    .s_axi_b_arlen   ( tiny_npu_d_m_axi_arlen         ),
    .s_axi_b_arsize  ( tiny_npu_d_m_axi_arsize        ),
    .s_axi_b_arburst ( tiny_npu_d_m_axi_arburst       ),
    .s_axi_b_arlock  ( tiny_npu_d_m_axi_arlock        ),
    .s_axi_b_arcache ( tiny_npu_d_m_axi_arcache       ),
    .s_axi_b_arprot  ( tiny_npu_d_m_axi_arprot        ),
    .s_axi_b_arvalid ( tiny_npu_d_m_axi_arvalid && tiny_npu_d_m_axi_ar_in_range       ),
    .s_axi_b_arready ( tiny_npu_d_m_axi_ar_ram_ready       ),
    .s_axi_b_rid     ( tiny_npu_d_m_axi_rid           ),
    .s_axi_b_rdata   ( tiny_npu_d_m_axi_rdata         ),
    .s_axi_b_rresp   ( tiny_npu_d_m_axi_rresp         ),
    .s_axi_b_rlast   ( tiny_npu_d_m_axi_rlast         ),
    .s_axi_b_rvalid  ( tiny_npu_d_m_axi_rvalid        ),
    .s_axi_b_rready  ( tiny_npu_d_m_axi_rready        )
);





endmodule
